import warnings; warnings.filterwarnings('ignore')
import pandas as pd
import numpy as np
from itertools import combinations
from sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor, HistGradientBoostingRegressor, ExtraTreesRegressor
from catboost import CatBoostRegressor

train = pd.read_csv('b3_htsteel_toughness_pareto_train.csv')
pool = pd.read_csv('b3_htsteel_toughness_pareto_pool.csv')
feat_cols = [c for c in train.columns if 'strength' not in c and 'toughness' not in c]
Xtr = train[feat_cols].values
Xpo = pool[feat_cols].values
ys_tr = train['yield strength (MPa)'].values
yt_tr = train['toughness (J)'].values

# Weights chosen from CV
W_YS = {'HGB': 0.7, 'RF': 0.1, 'CB': 0.2}
W_T  = {'CB': 0.55, 'GB': 0.25, 'ET': 0.2}

def make(name, seed=0):
    if name == 'RF':
        return RandomForestRegressor(n_estimators=500, random_state=seed)
    if name == 'ET':
        return ExtraTreesRegressor(n_estimators=500, random_state=seed)
    if name == 'GB':
        return GradientBoostingRegressor(n_estimators=400, max_depth=2, learning_rate=0.04, random_state=seed)
    if name == 'HGB':
        return HistGradientBoostingRegressor(max_iter=400, random_state=seed)
    if name == 'CB':
        return CatBoostRegressor(iterations=400, depth=4, learning_rate=0.06, loss_function='RMSE', verbose=0, random_seed=seed)

# Fit and predict for both objectives
preds = {}
for obj_name, ytr, W in [('YS', ys_tr, W_YS), ('T', yt_tr, W_T)]:
    p = np.zeros(len(pool))
    tot = sum(W.values())
    for name, w in W.items():
        m = make(name)
        m.fit(Xtr, ytr)
        p += (w / tot) * m.predict(Xpo)
    preds[obj_name] = p

pool['pYS'] = preds['YS']
pool['pT'] = preds['T']

def pareto_idx(pts):
    n = len(pts)
    keep = np.ones(n, bool)
    for i in range(n):
        for j in range(n):
            if i == j: continue
            if np.all(pts[j] >= pts[i]) and np.any(pts[j] > pts[i]):
                keep[i] = False
                break
    return np.where(keep)[0]

front_idx = pareto_idx(pool[['pYS', 'pT']].values)
print(f'Predicted non-dominated pool candidates: {len(front_idx)}')
print(pool.iloc[np.sort(front_idx)][['candidate_id','pYS','pT']].sort_values('pYS', ascending=False).to_string())

# Normalize using train ranges (both obj positive) and search exhaustive over the predicted front
def hv(points, ref=(0,0)):
    # 2-objective max-max hypervolume
    pts = sorted(points.tolist(), key=lambda p: (-p[0], -p[1]))
    hv_, prev_y = 0.0, ref[1]
    best_width_credit = None
    for p in pts:
        if p[1] <= prev_y: continue
        hv_ += (p[0] - ref[0]) * (p[1] - prev_y)
        prev_y = p[1]
    return hv_

# For normalized HV use min-max normalization on train objective range
ymin = np.array([ys_tr.min(), yt_tr.min()])
ymax = np.array([ys_tr.max(), yt_tr.max()])
p_norm = (pool[['pYS','pT']].values - ymin) / (ymax - ymin)

# Exhaustive search over non-dominated candidate set (front) but also consider dominated ones can still contribute? 
# For max-max in 2D, adding a dominated point never increases HV, so front-only suffices.
cand = np.sort(front_idx)
best = None
for combo in combinations(range(len(cand)), min(5, len(cand))):
    idxs = [cand[i] for i in combo]
    v = hv(p_norm[idxs])
    if best is None or v > best[0]:
        best = (v, idxs)
sel = pool.iloc[best[1]]
print('\nBest 5 by predicted (normalized) HV:')
print(sel[['candidate_id','pYS','pT']].sort_values('pYS', ascending=False).to_string())
print('HV =', best[0])
sel.to_csv('/tmp/selection.csv', index=False)
